syntax:
declaration-specifiers variable_name1, variable_name2,...; 

Where:
declaration-specifiers:  Data type (e.g., int, char, float, double) and optionally qualifiers (e.g., const, volatile).
variable_name: A valid C identifier.
Initialization:  declaration-specifiers variable_name = initial_value;

code_example:
#include <stdio.h>

int main() {
  int age = 30;                // Integer variable initialized to 30
  float price = 99.99f;      // Floating-point variable initialized to 99.99
  char initial = 'J';         // Character variable initialized to 'J'
  const double PI = 3.14159; // Constant double initialized to PI
  int count;                   // Integer variable declared but not initialized

  printf("Age: %d\n", age);
  printf("Price: %f\n", price);
  printf("Initial: %c\n", initial);
  printf("PI: %lf\n", PI);
  //count is used uninitialized, this is BAD practice and could lead to unexpected results
  printf("Count (Uninitialized): %d\n", count);
  return 0;
}
